import{_ as c,C as a,o as e,c as n,a0 as o,b as r,w as s,a as i,E as h,a1 as l}from"./chunks/framework.DhQjJcnt.js";const T=JSON.parse('{"title":"Tests-docs (resource)","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/tests-docs.md","filePath":"artifacts/tests-docs.md"}'),g={name:"artifacts/tests-docs.md"};function p(u,t,m,b,k,y){const d=a("Mermaid");return e(),n("div",null,[t[1]||(t[1]=o(`<h1 id="tests-docs-resource" tabindex="-1">Tests-docs (resource) <a class="header-anchor" href="#tests-docs-resource" aria-label="Permalink to &quot;Tests-docs (resource)&quot;">​</a></h1><p>Vai trò <strong>Tests-docs</strong> trong bốn nhóm artifacts: <a href="./">index.md</a>. Trang này mô tả <strong>chuẩn nội dung và cấu trúc</strong> của nhóm <strong>tests-docs</strong> trên disk.</p><p><strong>Tests-docs</strong> là SSOT <strong>tài liệu kiểm thử</strong> — kịch bản cross-flow (<code>SC-*</code>), testcase theo màn/API (<code>TC-*.yaml</code>), ma trận phân vùng tương đương (<code>testMatrix</code>), trace về bundle trên <strong>docs</strong>. Đây là nơi team trả lời <strong>kiểm gì</strong> và <strong>đúng nghiệp vụ nào</strong>; <strong>không</strong> phải repo chạy Playwright (→ <a href="./code.html">code.md</a> · <strong>e2e-root</strong>).</p><hr><h2 id="tests-docs-chua-nhung-gi" tabindex="-1">Tests-docs chứa những gì? <a class="header-anchor" href="#tests-docs-chua-nhung-gi" aria-label="Permalink to &quot;Tests-docs chứa những gì?&quot;">​</a></h2><ul><li><strong>Scenario (<code>SC-*</code>):</strong> luồng E2E <strong>xuyên nhiều màn / module</strong>, bám <code>FLOW-*</code> trên docs hub.</li><li><strong>Testcase (<code>TC-*.yaml</code>):</strong> kế hoạch kiểm <strong>theo function leaf</strong> (một <code>W-*</code> / một màn chính), mirror path docs.</li><li><strong>Catalog / locale (tùy init):</strong> <code>catalog/locale.yaml</code> — tiêu đề section khi render.</li><li><strong>Authoring (máy):</strong> sửa <code>TC-*.yaml</code> / <code>SC-*.yaml</code> — schema, <code>testMatrix</code>, trace, gate.</li><li><strong>Đọc cho team (người):</strong> <code>cases:render</code> → <code>TC-*.md</code> cạnh YAML — <strong>user case step-by-step</strong> (precondition → bước 1, 2, 3… → kết quả mong đợi); ma trận/field kỹ thuật gom trong <code>&lt;details&gt;</code>. Team review/walkthrough trên <strong>MD</strong>; <strong>không</strong> sửa tay MD thay YAML.</li></ul><p><strong>Không đặt ở tests-docs:</strong> <code>*.bundle.yaml</code>, <code>ir/*</code>, spec nghiệp vụ; <strong>không</strong> coi <code>testcases/*.yaml</code> cạnh code FE là SSOT hub (có thể là bản sinh hoặc mirror sau <code>testcase:gen</code> — SSOT plan vẫn ưu tiên hub <code>cases/**</code> khi team dùng FlowGrid tests-docs).</p><hr><h2 id="van-hanh-team-vs-deliverable-excel" tabindex="-1">Vận hành team vs deliverable (Excel) <a class="header-anchor" href="#van-hanh-team-vs-deliverable-excel" aria-label="Permalink to &quot;Vận hành team vs deliverable (Excel)&quot;">​</a></h2><p>Nhiều team vẫn <strong>bàn giao UAT / khách hàng</strong> bằng <strong>template Excel</strong> testcase (cột: ID, mô tả bước, data, kết quả mong đợi, pass/fail…). FlowGrid <strong>không</strong> thay quy trình bàn giao đó — nhưng <strong>tách rõ hai lớp tài liệu</strong> để không có hai SSOT cãi nhau.</p><table tabindex="0"><thead><tr><th>Lớp</th><th>Mục đích</th><th>Định dạng &amp; nơi lưu</th><th>Ai sửa khi đổi nghiệp vụ</th></tr></thead><tbody><tr><td><strong>Vận hành (SSOT hub)</strong></td><td>Grill, <code>cases:gate</code>, trace bundle/docs</td><td><strong>Ghi:</strong> YAML. <strong>Đọc:</strong> Markdown user case từng bước (<code>cases:render</code> → <code>TC-*.md</code>)</td><td>Sửa YAML (<code>/testcase</code>, <code>/scenario</code>) → <code>cases:render</code></td></tr><tr><td><strong>Deliverable (bàn giao)</strong></td><td>Ký UAT, audit khách, archive theo hợp đồng — <strong>không</strong> feed codegen/gate</td><td><strong>Excel</strong> (<code>.xlsx</code>) theo template dự án — đặt tách path, vd. <code>deliverables/testcases/</code>, <code>exports/uat/</code> hoặc drive release <strong>có version</strong></td><td><strong>Xuất từ</strong> SSOT hub sau khi chốt; không coi file Excel là nguồn cập nhật ngược vào gate</td></tr></tbody></table><p><strong>Nguyên tắc:</strong></p><ul><li><strong>SSOT trên disk</strong> = YAML (<code>TC-*</code>, <code>SC-*</code>) — audit, automation, trace <code>W-*</code> / <code>AC-*</code>.</li><li><strong>Bản team đọc</strong> = Markdown <strong>user case step-by-step</strong> (sinh từ YAML, không chỉnh tay); Excel deliverable xuất <strong>sau</strong> bản đã chốt trên YAML/MD nội bộ.</li><li><strong>Excel</strong> = <strong>ảnh chụp deliverable</strong> theo template khách/PMO. Điền tay trên Excel trong UAT session là OK; nếu kết quả UAT <strong>đổi</strong> kỳ vọng kiểm thử lâu dài → cập nhật lại <strong>docs</strong> (nếu sai yêu cầu) và <strong>YAML hub</strong> (nếu sai plan), rồi <strong>re-export</strong> Excel cho bản bàn giao mới.</li><li><strong>Cấm nhầm:</strong> merge PR chỉ sửa <code>.xlsx</code> mà không cập nhật <code>TC-*.yaml</code> tương ứng — team mất trace và <code>cases:gate</code> / automation lệch Excel.</li></ul><p><strong>Luồng gợi ý (team quen Excel):</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs bundle (user story, AC)</span></span>
<span class="line"><span>    → tests-docs TC-*.yaml (+ SC-* nếu cross-flow)</span></span>
<span class="line"><span>    → cases:render → TC-*.md (user case từng bước — team đọc)</span></span>
<span class="line"><span>    → export Excel (template dự án) → deliverables/…  [UAT / khách]</span></span>
<span class="line"><span>    → testcase:gen → Playwright (e2e-root)             [automation — tùy team]</span></span></code></pre></div><p>Export Excel có thể là script nội bộ, macro template, hoặc bước thủ công copy từ MD — FlowGrid <strong>chuẩn hóa SSOT</strong> ở YAML; công cụ export Excel <strong>không</strong> bắt buộc trong core CLI (team gắn pipeline riêng nếu cần).</p><hr><h2 id="ba-lane-—-khong-nham" tabindex="-1">Ba lane — không nhầm <a class="header-anchor" href="#ba-lane-—-khong-nham" aria-label="Permalink to &quot;Ba lane — không nhầm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lane</th><th>Root / pointer</th><th>Vai trò</th></tr></thead><tbody><tr><td><strong>Docs</strong></td><td><code>FLOWGRID_DOCS_ROOT</code></td><td>SSOT nghiệp vụ: bundle, acceptance, <code>FLOW-*</code> product</td></tr><tr><td><strong>Tests-docs</strong></td><td><code>FLOWGRID_TESTS_DOC</code></td><td>SSOT <strong>plan</strong> kiểm thử: <code>cases/**</code>, <code>scenarios/**</code></td></tr><tr><td><strong>Code (e2e-root)</strong></td><td>repo FE, <code>--e2e-root</code></td><td><strong>Chạy</strong> automation: Playwright <code>.spec.ts</code>, PO, mock runtime</td></tr></tbody></table><p>Sai <strong>yêu cầu</strong> → sửa <strong>docs</strong> (và testcase liên quan) trước code. Gap <strong>coverage</strong> hoặc ma trận thiếu facet → sửa tests-docs. Lệch <strong>script chạy</strong> → code/e2e-root.</p><hr><h2 id="trien-khai-root" tabindex="-1">Triển khai root <a class="header-anchor" href="#trien-khai-root" aria-label="Permalink to &quot;Triển khai root&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kiểu</th><th>Khi dùng</th></tr></thead><tbody><tr><td><strong>Repo test riêng</strong></td><td>Project type <strong>Test</strong>, hoặc FE/BE/Fullstack trỏ <code>FLOWGRID_TESTS_DOC</code> sang repo/path khác (vd. <code>tests/fe-hub</code>, <code>base-tests</code>).</td></tr><tr><td><strong>Tests-docs in-repo</strong></td><td>Dự án nhỏ: <code>tests/</code>, <code>qa-docs/</code> trong repo FE — vẫn là <strong>tests-docs resource</strong> về nghĩa.</td></tr></tbody></table><h3 id="flowgrid" tabindex="-1">FlowGrid <a class="header-anchor" href="#flowgrid" aria-label="Permalink to &quot;FlowGrid&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>FLOWGRID_TESTS_DOC</code></td><td>Root tests-docs (CLI, audit, skills <code>/testcase</code>, <code>/scenario</code>).</td></tr><tr><td><code>.flowgrid/config.json</code></td><td>Ghi path tests-docs sau <code>init</code>.</td></tr><tr><td><code>--tests-docs</code></td><td>Flag khi engine/audit cần trỏ hub testcase (cùng ý env root).</td></tr><tr><td><code>FLOWGRID_DOCS_ROOT</code></td><td>Bắt buộc khi <code>cases:gate --strict</code> / audit testcase cần đọc <strong>bundle</strong> cùng leaf docs.</td></tr></tbody></table><p>Chi tiết env/flag &amp; init: <code>flowgrid doctor</code> — <a href="./../references/cli-and-commands.html">references/cli-and-commands.md</a>.</p><hr><h2 id="cay-thu-muc-đieu-huong" tabindex="-1">Cây thư mục (điều hướng) <a class="header-anchor" href="#cay-thu-muc-đieu-huong" aria-label="Permalink to &quot;Cây thư mục (điều hướng)&quot;">​</a></h2><p>Root = tests-docs hub. Path <strong>mirror</strong> docs hub (bỏ prefix <code>surfaces/</code> khi map sang <code>cases/</code> hoặc <code>scenarios/</code> — xem bảng dưới).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catalog/</span></span>
<span class="line"><span>└─ locale.yaml                    # memberLocale, headings — cho cases:render</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cases/                            # testcase plan — TC-*.yaml (SSOT)</span></span>
<span class="line"><span>└─ &lt;mirror-docs-path&gt;/            # vd. admin/CMP-01-auth/01/01/login/</span></span>
<span class="line"><span>   ├─ TC-AUTH-01.yaml</span></span>
<span class="line"><span>   └─ TC-AUTH-01.md              # user case step-by-step (render) — không sửa tay</span></span>
<span class="line"><span></span></span>
<span class="line"><span>scenarios/                        # cross-flow — SC-* (YAML; có thể kèm SC-*.md review)</span></span>
<span class="line"><span>└─ &lt;mirror-FLOW-path&gt;/            # thư mục = tên FLOW (không .md)</span></span>
<span class="line"><span>   └─ FLOW-checkout/</span></span>
<span class="line"><span>      └─ SC-CHK-01.yaml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>plans/                            # tùy dự án — readiness / batch plan (optional)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>index.md                          # cases:render có thể tạo/cập nhật index section</span></span></code></pre></div><p><strong>Cấm path phẳng ad-hoc:</strong> <code>cases/admin/auth/W-…</code> khi docs thật là <code>surfaces/admin/CMP-*/…</code> — path <strong>phải</strong> khớp cấu trúc docs (cluster số <code>02/01/…</code> giữ nguyên).</p><h3 id="mirror-cases-↔-function-leaf-docs" tabindex="-1">Mirror <code>cases/</code> ↔ function leaf docs <a class="header-anchor" href="#mirror-cases-↔-function-leaf-docs" aria-label="Permalink to &quot;Mirror \`cases/\` ↔ function leaf docs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Docs (leaf function)</th><th>Tests-docs</th></tr></thead><tbody><tr><td><code>surfaces/&lt;surface&gt;/CMP-*/&lt;NN…&gt;/&lt;slug&gt;/</code> (<code>*.bundle.yaml</code>)</td><td><code>cases/&lt;surface&gt;/CMP-*/&lt;NN…&gt;/&lt;slug&gt;/TC-*.yaml</code></td></tr></tbody></table><p>Ví dụ:</p><ul><li>Docs: <code>surfaces/admin/CMP-ADM-002/02/01/login/login.bundle.yaml</code></li><li>Tests: <code>cases/admin/CMP-ADM-002/02/01/login/TC-LOGIN-01.yaml</code></li></ul><h3 id="mirror-scenarios-↔-flow-md-docs" tabindex="-1">Mirror <code>scenarios/</code> ↔ <code>FLOW-*.md</code> docs <a class="header-anchor" href="#mirror-scenarios-↔-flow-md-docs" aria-label="Permalink to &quot;Mirror \`scenarios/\` ↔ \`FLOW-*.md\` docs&quot;">​</a></h3><p>Chỉ tạo scenario khi file <strong><code>FLOW-*.md</code></strong> đã có trên docs (không lấy nguồn từ <code>common/yaml/</code> hay <code>common/patterns/</code>).</p><p>Thứ tự tìm FLOW trên docs (cùng LCA common):</p><ol><li><code>surfaces/&lt;surface&gt;/&lt;CMP&gt;/&lt;NN&gt;/common/processes/FLOW-*.md</code></li><li><code>surfaces/&lt;surface&gt;/&lt;CMP&gt;/common/processes/FLOW-*.md</code></li><li><code>surfaces/&lt;surface&gt;/common/processes/FLOW-*.md</code></li><li><code>surfaces/common/processes/FLOW-*.md</code></li><li><code>architecture/03-business-process/FLOW-*.md</code> (catalog / luồng kỹ thuật — chỉ khi team test theo FLOW kỹ thuật)</li></ol><table tabindex="0"><thead><tr><th>Docs FLOW path</th><th>Tests hub scenarios</th></tr></thead><tbody><tr><td><code>surfaces/&lt;rest&gt;/common/processes/FLOW-checkout.md</code></td><td><code>scenarios/&lt;rest&gt;/common/processes/FLOW-checkout/SC-*.yaml</code></td></tr><tr><td><code>architecture/03-business-process/FLOW-checkout.md</code></td><td><code>scenarios/architecture/03-business-process/FLOW-checkout/SC-*.yaml</code></td></tr></tbody></table><p><strong>Không</strong> flatten <code>scenarios/auth/…</code>. <strong>Không</strong> dùng <code>common/</code> legacy một cấp ở root scenarios.</p><hr><h2 id="đoc-ssot-nghiep-vu-truoc-khi-viet-test" tabindex="-1">Đọc SSOT nghiệp vụ trước khi viết test <a class="header-anchor" href="#đoc-ssot-nghiep-vu-truoc-khi-viet-test" aria-label="Permalink to &quot;Đọc SSOT nghiệp vụ trước khi viết test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc</th><th>Rule</th></tr></thead><tbody><tr><td>Nguồn coverage</td><td>Đọc <strong>toàn bộ</strong> <code>*.bundle.yaml</code> cùng leaf docs — <strong>không</strong> chỉ <code>ir/spec.yaml</code> + <code>ir/design.yaml</code> khi grill testcase</td></tr><tr><td>Bundle thiếu story/AC</td><td><strong>Dừng</strong> — handoff <code>/spec</code> hoặc <code>/update-spec</code> trên docs; <strong>không</strong> bịa testcase</td></tr><tr><td><code>flowgrid check</code> / split lệch</td><td>Reconcile bundle ↔ <code>ir/*</code> trên docs trước testcase</td></tr><tr><td>Trace</td><td><code>traceability</code> trên TC: <code>bundleScreen</code>, <code>bundleScenarios[]</code>, <code>acceptanceRefs[]</code> (<code>AC-01</code>…), <code>actionRefs[]</code> (<code>btn_*</code>) — bắt buộc cho <code>cases:gate --strict</code></td></tr><tr><td>Codegen Playwright</td><td>FE vẫn đọc <code>ir/design.yaml</code> sau split; <strong>thiết kế</strong> testcase bám <strong>bundle</strong></td></tr></tbody></table><hr><h2 id="testcase-tc-yaml-schema-v2" tabindex="-1">Testcase <code>TC-*.yaml</code> (schema v2) <a class="header-anchor" href="#testcase-tc-yaml-schema-v2" aria-label="Permalink to &quot;Testcase \`TC-*.yaml\` (schema v2)&quot;">​</a></h2><p>SSOT schema: <code>schemas/testcase.schema.json</code> (package FlowGrid). Mẫu vàng: <code>harness/tests/templates/TC.example.yaml</code>.</p><table tabindex="0"><thead><tr><th>Yêu cầu</th><th>Ghi chú</th></tr></thead><tbody><tr><td><code>schemaVersion: 2</code></td><td>Bắt buộc cho release gate</td></tr><tr><td><code>id</code></td><td><code>TC-…</code> ngắn</td></tr><tr><td><code>title</code></td><td>Ngắn (~15–20 ký tự); giải thích dài → <code>description</code> / <code>story</code></td></tr><tr><td><code>refs</code></td><td><code>screen</code> (<code>W-*</code> / <code>API-*</code>), <code>scenario</code> (<code>SC-*</code>), <code>module</code> (<code>CMP-*</code>)</td></tr><tr><td><code>testMatrix</code></td><td>Facet: <code>positive_boundary</code>, <code>negative_length</code>, <code>negative_format</code>, <code>negative_duplicate</code>, <code>concurrency_double_submit</code>, <code>network_interruption</code>, …</td></tr><tr><td><code>steps</code></td><td>≥ 1 bước (ngôn ngữ QA / BDD)</td></tr><tr><td><code>coverage</code></td><td>Enum: <code>happy</code>, <code>validation</code>, <code>boundary</code>, <code>authorization</code>, <code>exception</code>, <code>concurrency</code>, …</td></tr><tr><td><code>testIds.required</code></td><td>Khớp <code>ui.testIds</code> / design bundle sau split — quy ước đặt tên &amp; markup FE: <a href="./code.html#e2e-testids">code.md § testId</a></td></tr><tr><td><code>genType</code></td><td><code>e2e</code> (plan hub — sinh spec ở e2e-root qua <code>testcase:gen</code>)</td></tr></tbody></table><p><strong>YAML thuần:</strong> không nhúng biểu thức JS (<code>&quot;a&quot;.repeat(256)</code>); ghi chuỗi literal hoặc quote đúng.</p><hr><h2 id="scenario-sc" tabindex="-1">Scenario <code>SC-*</code> <a class="header-anchor" href="#scenario-sc" aria-label="Permalink to &quot;Scenario \`SC-*\`&quot;">​</a></h2><ul><li>Mô tả <strong>hành trình xuyên flow</strong>; frontmatter/list <strong><code>screens: [W-…, …]</code></strong> cho mọi màn chạm tới.</li><li>Sau khi viết: <code>flowgrid audit scenario &lt;file&gt; --tests-docs &lt;hub&gt;</code> — lấp gap <code>SC_SCREEN_NO_TC</code> bằng <code>cases/**/TC-*.yaml</code> hoặc <code>coverage_deferred</code> + <code>QA-*</code> trên docs.</li><li>Review dài có thể dùng <code>SC-*.md</code> (IEEE 29119 boundary table + Gherkin); <strong>contract machine</strong> ưu tiên YAML theo skill <code>/scenario</code>.</li></ul><p>Mẫu tham khảo: <code>harness/tests/templates/SC.example.md</code>.</p><hr><h2 id="id-chuan-tests-lane" tabindex="-1">ID chuẩn (tests lane) <a class="header-anchor" href="#id-chuan-tests-lane" aria-label="Permalink to &quot;ID chuẩn (tests lane)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prefix</th><th>Vai trò</th></tr></thead><tbody><tr><td><code>SC-*</code></td><td>Scenario cross-flow</td></tr><tr><td><code>TC-*</code></td><td>Testcase plan (file YAML)</td></tr><tr><td><code>W-*</code> / <code>API-*</code></td><td>Tham chiếu màn/contract trên docs (trong <code>refs</code>, trace)</td></tr><tr><td><code>FLOW-*</code></td><td>Tham chiếu luồng docs (scenario folder name)</td></tr><tr><td><code>CMP-*</code></td><td>Module trong <code>refs.module</code></td></tr><tr><td><code>QA-*</code></td><td>Open question trên docs khi defer coverage</td></tr></tbody></table><p><code>SC-*</code> / <code>TC-*</code> <strong>không</strong> thay <code>DEP-*</code> (deployment) hay target kiến trúc cũ <code>CTR-*</code>.</p><hr><h2 id="lenh-gate-tham-chieu" tabindex="-1">Lệnh &amp; gate (tham chiếu) <a class="header-anchor" href="#lenh-gate-tham-chieu" aria-label="Permalink to &quot;Lệnh &amp; gate (tham chiếu)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc</th><th>Gợi ý lệnh</th></tr></thead><tbody><tr><td>Validate schema YAML</td><td><code>flowgrid cases:check</code> / <code>pnpm cases:check</code></td></tr><tr><td>YAML → MD user case (từng bước)</td><td><code>flowgrid cases:render</code> / <code>pnpm cases:render</code></td></tr><tr><td>Coverage spec ↔ plan</td><td><code>flowgrid cases:coverage</code></td></tr><tr><td>Audit một TC + bundle</td><td><code>flowgrid audit testcase &lt;TC.yaml&gt; --bundle &lt;path/to.bundle.yaml&gt;</code></td></tr><tr><td>Release gate (IT/release)</td><td><code>flowgrid cases:gate [--strict] [--docs-root $FLOWGRID_DOCS_ROOT]</code></td></tr><tr><td>Sinh Playwright UI skeleton</td><td><code>testcase:gen</code> (<code>genType: e2e</code>) trên <strong>e2e-root</strong></td></tr><tr><td>Sinh Playwright API hook spec</td><td><code>testcase:gen:api</code> (<code>genType: api-e2e</code>) → <code>tests/api-e2e/**/*.api.spec.ts</code></td></tr></tbody></table><p><strong><code>cases:gate --strict</code>:</strong> JSON Schema v2 + audit testcase + <code>traceability</code> bundle + facet ma trận theo màn + (tùy) coverage scenario. Chạy trước wire/release khi team bật gate.</p><p>Mốc workflow: <a href="./../workflows/gates.html">workflows/gates.md</a> · tham số audit: <a href="./../references/cli-and-commands.html#audit--harness-pr-workflow">references/cli-and-commands.md</a>.</p><hr><h2 id="integration-api--webhook-tc" tabindex="-1">Integration API / webhook (TC plan) <a class="header-anchor" href="#integration-api--webhook-tc" aria-label="Permalink to &quot;Integration API / webhook (TC plan) {#integration-api--webhook-tc}&quot;">​</a></h2><p>Dùng khi docs có <strong>surface tích hợp</strong> (<code>surfaces/integrations/</code>, <code>/api-integration</code>, <code>/grill-integration-spec</code>) — API cho bên thứ 3, webhook inbound/outbound.</p><h3 id="ssot-tren-tests-docs" tabindex="-1">SSOT trên tests-docs <a class="header-anchor" href="#ssot-tren-tests-docs" aria-label="Permalink to &quot;SSOT trên tests-docs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trường</th><th>Gợi ý</th></tr></thead><tbody><tr><td><code>genType</code></td><td><strong><code>api-e2e</code></strong> (bắt buộc cho <code>testcase:gen:api</code>) · UI portal dùng <code>e2e</code></td></tr><tr><td><code>refs.screen</code></td><td><code>API-*</code> (schema bắt <code>^API-</code> khi <code>api-e2e</code>)</td></tr><tr><td><code>api</code></td><td><code>baseUrlEnv</code>, <code>baseURL</code>, <code>defaultHeaders</code></td></tr><tr><td><code>apiSteps[]</code></td><td><code>method</code>, <code>path</code>, <code>expectStatus</code>, <code>body</code>, <code>headers</code>, <code>expectJson</code></td></tr><tr><td><code>tags</code></td><td><code>integration</code>, <code>webhook</code>, <code>partner-api</code>, <code>contract-postman</code></td></tr><tr><td>Mẫu YAML</td><td><code>harness/tests/templates/TC.example-api.yaml</code></td></tr></tbody></table><p>Skill author: <strong><code>/test-api</code></strong> · grill plan vẫn qua <code>/grill-testcase</code> + <code>audit testcase --bundle</code>.</p><h3 id="sinh-automation-playwright-request" tabindex="-1">Sinh automation (Playwright <code>request</code>) <a class="header-anchor" href="#sinh-automation-playwright-request" aria-label="Permalink to &quot;Sinh automation (Playwright \`request\`)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flowgrid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testcase:gen:api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --testcase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cases/.../TC-PARTNER-EXPORT.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flowgrid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testcase:gen:api:dry</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TC-PARTNER-EXPORT</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flowgrid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testcase:gen:api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flowgrid:api-e2e-gen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --testcase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span></code></pre></div><ul><li>Chạy trên <strong>e2e-root</strong> (repo FE/code); input YAML từ <strong>tests-docs</strong> hub (<code>FLOWGRID_TESTS_DOC</code>).</li><li>Output: <code>tests/api-e2e/&lt;module&gt;/&lt;TC-id&gt;.api.spec.ts</code>.</li><li>Env: <code>FLOWGRID_API_TEST_BASE_URL</code> hoặc tên trong <code>api.baseUrlEnv</code>.</li></ul><h3 id="playwright-vs-postman-vs-be-test" tabindex="-1">Playwright vs Postman vs BE test <a class="header-anchor" href="#playwright-vs-postman-vs-be-test" aria-label="Permalink to &quot;Playwright vs Postman vs BE test&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nhu cầu</th><th>Gợi ý</th></tr></thead><tbody><tr><td>Hook/partner HTTP trong lane FlowGrid</td><td><strong><code>genType: api-e2e</code></strong> + <code>testcase:gen:api</code> (Playwright <code>request</code>)</td></tr><tr><td>UI tạo data → partner đọc API</td><td><strong><code>SC-*</code></strong> + 2 TC: <code>e2e</code> (UI) + <code>api-e2e</code> (hook); CI truyền <code>orderId</code> qua env giữa 2 job hoặc một spec hybrid tay</td></tr><tr><td>Collection đối tác / HMAC phức tạp</td><td>Postman + Newman trong <code>integrations/postman/</code>; tag TC <code>contract-postman</code> (chưa gen từ FlowGrid)</td></tr><tr><td>Chữ ký webhook, idempotency, DLQ</td><td>Test <strong>BE</strong> (Supertest/pytest/…) — không thay bằng tests-docs</td></tr></tbody></table>`,73)),(e(),r(l,null,{default:s(()=>[h(d,{id:"mermaid-865",class:"mermaid",graph:"flowchart%20LR%0A%20%20SC%5B%22SC-*%22%5D%0A%20%20TC_UI%5B%22TC%20genType%20e2e%22%5D%0A%20%20TC_API%5B%22TC%20genType%20api-e2e%22%5D%0A%20%20GEN_UI%5B%22testcase%3Agen%22%5D%0A%20%20GEN_API%5B%22testcase%3Agen%3Aapi%22%5D%0A%0A%20%20SC%20--%3E%20TC_UI%0A%20%20SC%20--%3E%20TC_API%0A%20%20TC_UI%20--%3E%20GEN_UI%0A%20%20TC_API%20--%3E%20GEN_API%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<p>Gate: <code>cases:check</code> (schema hỗ trợ <code>api-e2e</code>) · <code>cases:gate --strict</code> · <code>audit testcase</code> với bundle integration trên docs-hub.</p><hr><h2 id="skill-vai-tro-t-shaped" tabindex="-1">Skill &amp; vai trò (T-shaped) <a class="header-anchor" href="#skill-vai-tro-t-shaped" aria-label="Permalink to &quot;Skill &amp; vai trò (T-shaped)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Owner hub</th><th>Mục đích</th></tr></thead><tbody><tr><td><code>/testcase</code></td><td>tests-docs</td><td>Author <code>TC-*.yaml</code> UI (<code>genType: e2e</code>)</td></tr><tr><td><code>/test-api</code></td><td>tests-docs</td><td>Author <code>TC-*.yaml</code> API hook (<code>genType: api-e2e</code>)</td></tr><tr><td><code>/scenario</code></td><td>tests-docs</td><td>Author <code>SC-*</code> bám <code>FLOW-*</code></td></tr><tr><td><code>/grill-testcase</code></td><td>tests-docs</td><td>Grill plan YAML + bundle audit</td></tr><tr><td><code>/grill-test</code></td><td>tests-docs + e2e</td><td>Matrix TC ↔ PO ↔ UI spec</td></tr><tr><td><code>/test</code></td><td>e2e-root</td><td>Sửa Playwright sau gen</td></tr><tr><td><code>testcase:gen</code></td><td>CLI</td><td>UI plan → <code>tests/e2e/**/*.spec.ts</code></td></tr><tr><td><code>testcase:gen:api</code></td><td>CLI</td><td>API plan → <code>tests/api-e2e/**/*.api.spec.ts</code></td></tr></tbody></table><p>QA thường sở hữu tests-docs; dev tham gia grill và wire. Chi tiết skill: <a href="./../references/cli-and-commands.html">CLI &amp; skills</a> · harness <code>harness/tests/skills/</code>.</p><hr><h2 id="quan-he-voi-nhom-resource-khac" tabindex="-1">Quan hệ với nhóm resource khác <a class="header-anchor" href="#quan-he-voi-nhom-resource-khac" aria-label="Permalink to &quot;Quan hệ với nhóm resource khác&quot;">​</a></h2><ul><li><strong>Docs:</strong> định nghĩa hành vi và acceptance — tests-docs <strong>trace ngược</strong> bundle; không sửa nghiệp vụ trên hub test.</li><li><strong>Code:</strong> <code>testcase:gen</code> và Playwright <strong>thực thi</strong>; <code>ir/design.yaml</code> cho locator/testId runtime.</li><li><strong>DSL &amp; platform:</strong> tags <code>#e2e:*</code>, registry E2E — quy ước format trên generated spec, không thay <code>TC-*.yaml</code> SSOT.</li></ul><p>Thứ tự làm việc và lane E2E: <a href="./../workflows/test.html">workflows/test.md</a>.</p>',9))])}const f=c(g,[["render",p]]);export{T as __pageData,f as default};
